def mask_personal_information(s):
    if '@' in s:
        name,domain=s.lower().split('@');return name[0]+'*****'+name[-1]+'@'+domain
    digits=''.join(char for char in s if char.isdigit());local='***-***-'+digits[-4:]
    return ('+'+'*'*(len(digits)-10)+'-' if len(digits)>10 else '')+local

